import LessonDocument from "./LessonDocument";

const styles = "@import url('https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@300;400;500;700&family=Share+Tech+Mono&family=Rajdhani:wght@400;500;600;700&display=swap');\n\n  :root {\n    --bg: #0a0c0f;\n    --bg2: #0d1117;\n    --bg3: #111820;\n    --panel: #131a22;\n    --panel2: #1a2332;\n    --border: #1e3a5f;\n    --border2: #0f2540;\n    --green: #00ff88;\n    --green2: #00cc6a;\n    --cyan: #00d4ff;\n    --cyan2: #0099cc;\n    --yellow: #ffd700;\n    --orange: #ff8c00;\n    --red: #ff3b3b;\n    --purple: #9d4edd;\n    --blue: #2979ff;\n    --text: #c8d8e8;\n    --text2: #7a9bb5;\n    --text3: #4a6a85;\n    --mono: 'JetBrains Mono', monospace;\n    --sans: 'Rajdhani', sans-serif;\n  }\n\n  * { box-sizing: border-box; margin: 0; padding: 0; }\n  \n  body {\n    background: var(--bg);\n    color: var(--text);\n    font-family: var(--mono);\n    font-size: 13px;\n    line-height: 1.6;\n    min-height: 100vh;\n    overflow-x: hidden;\n  }\n\n  /* Scanline overlay */\n  body::before {\n    content: '';\n    position: fixed;\n    inset: 0;\n    background: repeating-linear-gradient(0deg, transparent, transparent 2px, rgba(0,255,136,0.015) 2px, rgba(0,255,136,0.015) 4px);\n    pointer-events: none;\n    z-index: 9999;\n  }\n\n  .container {\n    max-width: 1100px;\n    margin: 0 auto;\n    padding: 20px 16px;\n  }\n\n  /* ── TOP HEADER ── */\n  .sys-header {\n    background: linear-gradient(135deg, #0d1a2e 0%, #0a1520 100%);\n    border: 1px solid var(--border);\n    border-top: 3px solid var(--green);\n    padding: 20px 24px;\n    margin-bottom: 16px;\n    position: relative;\n    overflow: hidden;\n  }\n  .sys-header::after {\n    content: '';\n    position: absolute;\n    right: -60px; top: -60px;\n    width: 200px; height: 200px;\n    background: radial-gradient(circle, rgba(0,255,136,0.06) 0%, transparent 70%);\n    pointer-events: none;\n  }\n  .header-row {\n    display: flex;\n    align-items: flex-start;\n    justify-content: space-between;\n    flex-wrap: wrap;\n    gap: 12px;\n  }\n  .step-badge {\n    font-family: var(--sans);\n    font-size: 11px;\n    font-weight: 600;\n    letter-spacing: 3px;\n    text-transform: uppercase;\n    color: var(--green);\n    margin-bottom: 6px;\n    display: flex;\n    align-items: center;\n    gap: 8px;\n  }\n  .step-badge::before {\n    content: '';\n    display: inline-block;\n    width: 8px; height: 8px;\n    background: var(--green);\n    border-radius: 50%;\n    box-shadow: 0 0 8px var(--green);\n    animation: pulse 2s infinite;\n  }\n  @keyframes pulse { 0%,100%{opacity:1} 50%{opacity:0.4} }\n\n  .lesson-title {\n    font-family: var(--sans);\n    font-size: 26px;\n    font-weight: 700;\n    color: #fff;\n    letter-spacing: 1px;\n    line-height: 1.2;\n  }\n  .lesson-title span { color: var(--green); }\n\n  .meta-tags {\n    display: flex;\n    flex-wrap: wrap;\n    gap: 8px;\n    margin-top: 10px;\n  }\n  .tag {\n    padding: 3px 10px;\n    border-radius: 2px;\n    font-size: 11px;\n    font-weight: 500;\n    letter-spacing: 1px;\n    text-transform: uppercase;\n    font-family: var(--sans);\n  }\n  .tag-green { background: rgba(0,255,136,0.12); color: var(--green); border: 1px solid rgba(0,255,136,0.3); }\n  .tag-cyan  { background: rgba(0,212,255,0.1);  color: var(--cyan);  border: 1px solid rgba(0,212,255,0.3); }\n  .tag-yellow{ background: rgba(255,215,0,0.1);  color: var(--yellow);border: 1px solid rgba(255,215,0,0.3); }\n  .tag-purple{ background: rgba(157,78,221,0.12);color: var(--purple);border: 1px solid rgba(157,78,221,0.3);}\n  .tag-orange{ background: rgba(255,140,0,0.1);  color: var(--orange);border: 1px solid rgba(255,140,0,0.3);}\n\n  .sys-info {\n    text-align: right;\n    font-size: 11px;\n    color: var(--text3);\n    line-height: 1.8;\n  }\n  .sys-info span { color: var(--cyan); }\n\n  /* ── PANELS ── */\n  .panel {\n    background: var(--panel);\n    border: 1px solid var(--border2);\n    margin-bottom: 14px;\n    overflow: hidden;\n  }\n  .panel-header {\n    background: var(--panel2);\n    border-bottom: 1px solid var(--border);\n    padding: 8px 16px;\n    display: flex;\n    align-items: center;\n    gap: 10px;\n  }\n  .panel-icon { font-size: 14px; }\n  .panel-title {\n    font-family: var(--sans);\n    font-size: 13px;\n    font-weight: 600;\n    letter-spacing: 2px;\n    text-transform: uppercase;\n    color: var(--cyan);\n  }\n  .panel-num {\n    margin-left: auto;\n    font-size: 10px;\n    color: var(--text3);\n    letter-spacing: 1px;\n  }\n  .panel-body { padding: 18px 20px; }\n\n  /* ── CONCEPT EXPLANATION ── */\n  .concept-grid {\n    display: grid;\n    grid-template-columns: 1fr 1fr;\n    gap: 14px;\n  }\n  @media(max-width:640px){ .concept-grid { grid-template-columns:1fr; } }\n\n  .concept-block {\n    background: var(--bg3);\n    border: 1px solid var(--border2);\n    border-left: 3px solid var(--cyan);\n    padding: 14px;\n  }\n  .concept-block.green { border-left-color: var(--green); }\n  .concept-block.yellow { border-left-color: var(--yellow); }\n  .concept-block.purple { border-left-color: var(--purple); }\n  .concept-block.orange { border-left-color: var(--orange); }\n\n  .cb-title {\n    font-family: var(--sans);\n    font-size: 12px;\n    font-weight: 600;\n    letter-spacing: 2px;\n    text-transform: uppercase;\n    margin-bottom: 8px;\n    color: var(--cyan);\n  }\n  .concept-block.green .cb-title { color: var(--green); }\n  .concept-block.yellow .cb-title { color: var(--yellow); }\n  .concept-block.purple .cb-title { color: var(--purple); }\n  .concept-block.orange .cb-title { color: var(--orange); }\n\n  .cb-text { color: var(--text); font-size: 12.5px; line-height: 1.7; }\n\n  /* ── ARCHITECTURE DIAGRAM ── */\n  .arch-diagram {\n    background: var(--bg);\n    border: 1px solid var(--border2);\n    padding: 20px;\n    font-size: 12px;\n  }\n\n  .arch-layers {\n    display: flex;\n    flex-direction: column;\n    gap: 0;\n    max-width: 700px;\n    margin: 0 auto;\n  }\n\n  .layer {\n    display: flex;\n    align-items: stretch;\n    position: relative;\n  }\n\n  .layer-label {\n    width: 130px;\n    min-width: 130px;\n    display: flex;\n    align-items: center;\n    justify-content: flex-end;\n    padding-right: 14px;\n    font-size: 10px;\n    letter-spacing: 1.5px;\n    text-transform: uppercase;\n    color: var(--text3);\n    font-family: var(--sans);\n    font-weight: 600;\n  }\n\n  .layer-box {\n    flex: 1;\n    border: 1px solid;\n    padding: 10px 16px;\n    text-align: center;\n    position: relative;\n  }\n\n  .layer-arrow {\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    height: 22px;\n    color: var(--text3);\n    font-size: 16px;\n    padding-left: 130px;\n    letter-spacing: 0;\n  }\n\n  /* layer colors */\n  .l-app    { border-color: rgba(41,121,255,0.5); background: rgba(41,121,255,0.07); }\n  .l-shell  { border-color: rgba(0,212,255,0.5);  background: rgba(0,212,255,0.07); }\n  .l-syscall{ border-color: rgba(0,255,136,0.5);  background: rgba(0,255,136,0.07); }\n  .l-kernel { border-color: rgba(255,215,0,0.6);  background: rgba(255,215,0,0.08); }\n  .l-hw     { border-color: rgba(255,140,0,0.5);  background: rgba(255,140,0,0.07); }\n\n  .l-app    .layer-label { color: #5599ff; }\n  .l-shell  .layer-label { color: var(--cyan); }\n  .l-syscall .layer-label { color: var(--green); }\n  .l-kernel .layer-label { color: var(--yellow); }\n  .l-hw     .layer-label { color: var(--orange); }\n\n  .layer-name {\n    font-family: var(--sans);\n    font-size: 13px;\n    font-weight: 700;\n    letter-spacing: 1px;\n    margin-bottom: 2px;\n  }\n  .layer-sub { font-size: 11px; color: var(--text2); }\n\n  .layer-components {\n    display: flex;\n    gap: 6px;\n    flex-wrap: wrap;\n    justify-content: center;\n    margin-top: 6px;\n  }\n  .lc {\n    background: rgba(255,255,255,0.05);\n    border: 1px solid rgba(255,255,255,0.08);\n    padding: 2px 8px;\n    font-size: 10px;\n    color: var(--text2);\n    border-radius: 2px;\n  }\n\n  /* Kernel internals diagram */\n  .kernel-box {\n    border: 2px solid rgba(255,215,0,0.5);\n    background: rgba(255,215,0,0.04);\n    padding: 16px;\n    margin-top: 20px;\n    max-width: 700px;\n    margin-left: auto;\n    margin-right: auto;\n  }\n  .kernel-title {\n    font-family: var(--sans);\n    font-weight: 700;\n    font-size: 13px;\n    letter-spacing: 2px;\n    text-transform: uppercase;\n    color: var(--yellow);\n    text-align: center;\n    margin-bottom: 12px;\n    padding-bottom: 8px;\n    border-bottom: 1px solid rgba(255,215,0,0.2);\n  }\n  .kernel-grid {\n    display: grid;\n    grid-template-columns: repeat(3, 1fr);\n    gap: 8px;\n  }\n  @media(max-width:500px){ .kernel-grid{ grid-template-columns: 1fr 1fr; } }\n  .kc {\n    background: rgba(255,215,0,0.06);\n    border: 1px solid rgba(255,215,0,0.2);\n    padding: 8px 10px;\n    text-align: center;\n    font-size: 11px;\n    color: var(--yellow);\n  }\n  .kc-icon { font-size: 16px; display: block; margin-bottom: 3px; }\n  .kc-name { font-family: var(--sans); font-weight: 600; font-size: 11px; }\n  .kc-desc { font-size: 10px; color: var(--text3); margin-top: 2px; }\n\n  /* ── WORKFLOW ── */\n  .workflow {\n    display: flex;\n    flex-direction: column;\n    gap: 0;\n  }\n  .wf-step {\n    display: flex;\n    gap: 14px;\n    align-items: flex-start;\n    position: relative;\n  }\n  .wf-step:not(:last-child) .wf-line {\n    position: absolute;\n    left: 16px;\n    top: 32px;\n    bottom: -14px;\n    width: 1px;\n    background: linear-gradient(to bottom, var(--green), transparent);\n  }\n  .wf-dot {\n    width: 32px;\n    min-width: 32px;\n    height: 32px;\n    border-radius: 50%;\n    border: 2px solid var(--green);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    font-size: 11px;\n    font-weight: 700;\n    color: var(--green);\n    background: rgba(0,255,136,0.08);\n    flex-shrink: 0;\n    font-family: var(--sans);\n  }\n  .wf-content {\n    flex: 1;\n    background: var(--bg3);\n    border: 1px solid var(--border2);\n    padding: 10px 14px;\n    margin-bottom: 10px;\n  }\n  .wf-title {\n    font-family: var(--sans);\n    font-weight: 600;\n    font-size: 13px;\n    color: var(--green);\n    margin-bottom: 3px;\n  }\n  .wf-desc { font-size: 11.5px; color: var(--text2); }\n  .wf-cmd { \n    margin-top: 6px;\n    background: var(--bg);\n    padding: 4px 10px;\n    font-size: 11px;\n    color: var(--cyan);\n    border-left: 2px solid var(--cyan);\n  }\n\n  /* ── TERMINAL ── */\n  .terminal {\n    background: #050810;\n    border: 1px solid #1a2d45;\n    font-family: var(--mono);\n    overflow: hidden;\n  }\n  .term-bar {\n    background: #0d1520;\n    border-bottom: 1px solid #1a2d45;\n    padding: 7px 14px;\n    display: flex;\n    align-items: center;\n    gap: 8px;\n  }\n  .term-dot {\n    width: 10px; height: 10px;\n    border-radius: 50%;\n  }\n  .td-red { background: #ff5f57; }\n  .td-yellow { background: #febc2e; }\n  .td-green { background: #28c840; }\n  .term-title {\n    margin-left: 8px;\n    font-size: 11px;\n    color: var(--text3);\n    letter-spacing: 1px;\n    font-family: var(--sans);\n  }\n  .term-body { padding: 14px 18px; font-size: 12px; line-height: 1.8; }\n\n  .t-prompt { color: var(--green); }\n  .t-cmd    { color: #fff; }\n  .t-comment{ color: var(--text3); font-style: italic; }\n  .t-out    { color: var(--text2); display: block; margin-left: 0; }\n  .t-out2   { color: var(--cyan); display: block; }\n  .t-out3   { color: var(--yellow); display: block; }\n  .t-err    { color: var(--red); display: block; }\n  .t-section {\n    display: block;\n    margin: 10px 0 4px;\n    color: var(--text3);\n    font-size: 10px;\n    letter-spacing: 2px;\n    text-transform: uppercase;\n    border-top: 1px solid #1a2d45;\n    padding-top: 10px;\n  }\n  .t-line   { display: block; }\n\n  /* ── LINUX VS WINDOWS ── */\n  .compare-table {\n    width: 100%;\n    border-collapse: collapse;\n    font-size: 12px;\n  }\n  .compare-table th {\n    background: var(--panel2);\n    padding: 10px 14px;\n    text-align: left;\n    font-family: var(--sans);\n    font-size: 12px;\n    font-weight: 600;\n    letter-spacing: 1.5px;\n    text-transform: uppercase;\n    border-bottom: 2px solid var(--border);\n  }\n  .compare-table th:nth-child(1) { color: var(--text3); }\n  .compare-table th:nth-child(2) { color: var(--yellow); }\n  .compare-table th:nth-child(3) { color: var(--blue); }\n  .compare-table td {\n    padding: 9px 14px;\n    border-bottom: 1px solid var(--border2);\n    vertical-align: top;\n    color: var(--text2);\n  }\n  .compare-table td:first-child { color: var(--text); font-weight: 500; font-family: var(--sans); font-size: 12px; }\n  .compare-table tr:hover td { background: rgba(255,255,255,0.02); }\n  .yes { color: var(--green); font-weight: 600; }\n  .no  { color: var(--red);   font-weight: 600; }\n  .na  { color: var(--text3); }\n\n  /* ── SECURITY PANEL ── */\n  .sec-grid {\n    display: grid;\n    grid-template-columns: 1fr 1fr;\n    gap: 12px;\n  }\n  @media(max-width:640px){ .sec-grid{ grid-template-columns:1fr; } }\n\n  .sec-block {\n    background: var(--bg3);\n    border: 1px solid var(--border2);\n    padding: 14px;\n  }\n  .sb-title {\n    font-family: var(--sans);\n    font-size: 11px;\n    letter-spacing: 2px;\n    font-weight: 700;\n    text-transform: uppercase;\n    margin-bottom: 8px;\n    display: flex;\n    align-items: center;\n    gap: 6px;\n  }\n  .sb-title.red { color: var(--red); }\n  .sb-title.green { color: var(--green); }\n\n  .sb-list { list-style: none; }\n  .sb-list li {\n    padding: 4px 0;\n    font-size: 12px;\n    color: var(--text2);\n    display: flex;\n    gap: 8px;\n    align-items: flex-start;\n  }\n  .sb-list li::before { content: '›'; color: var(--text3); flex-shrink: 0; }\n\n  /* ── WHERE IS LINUX USED ── */\n  .use-grid {\n    display: grid;\n    grid-template-columns: repeat(3, 1fr);\n    gap: 10px;\n  }\n  @media(max-width:640px){ .use-grid{ grid-template-columns: 1fr 1fr; } }\n\n  .use-card {\n    background: var(--bg3);\n    border: 1px solid var(--border2);\n    padding: 14px 12px;\n    text-align: center;\n  }\n  .uc-icon { font-size: 22px; margin-bottom: 6px; }\n  .uc-name {\n    font-family: var(--sans);\n    font-weight: 700;\n    font-size: 13px;\n    color: var(--text);\n    margin-bottom: 4px;\n  }\n  .uc-desc { font-size: 10.5px; color: var(--text3); line-height: 1.5; }\n  .uc-pct {\n    margin-top: 8px;\n    font-size: 11px;\n    font-weight: 700;\n    font-family: var(--sans);\n  }\n\n  /* ── DISTRO MAP ── */\n  .distro-tree {\n    font-size: 12px;\n    color: var(--text2);\n    line-height: 1.9;\n    background: var(--bg);\n    border: 1px solid var(--border2);\n    padding: 16px 20px;\n  }\n  .dt-root { color: var(--yellow); font-weight: 700; font-family: var(--sans); font-size: 14px; }\n  .dt-branch { color: var(--cyan); font-weight: 600; }\n  .dt-leaf { color: var(--text2); }\n  .dt-indent1 { padding-left: 20px; }\n  .dt-indent2 { padding-left: 40px; }\n\n  /* ── CHECKLIST ── */\n  .checklist { list-style: none; }\n  .checklist li {\n    padding: 7px 0;\n    border-bottom: 1px solid var(--border2);\n    font-size: 12.5px;\n    display: flex;\n    align-items: flex-start;\n    gap: 10px;\n    color: var(--text2);\n  }\n  .checklist li:last-child { border-bottom: none; }\n  .chk { \n    width: 16px; height: 16px; min-width: 16px;\n    border: 1px solid var(--green);\n    background: rgba(0,255,136,0.1);\n    display: flex; align-items: center; justify-content: center;\n    font-size: 10px; color: var(--green);\n    margin-top: 1px;\n  }\n  .chk-domain {\n    font-family: var(--sans);\n    font-size: 10px;\n    font-weight: 600;\n    letter-spacing: 1px;\n    padding: 1px 6px;\n    border-radius: 2px;\n    margin-left: auto;\n    flex-shrink: 0;\n  }\n\n  /* ── SUMMARY ── */\n  .summary-grid {\n    display: grid;\n    grid-template-columns: repeat(3, 1fr);\n    gap: 10px;\n    margin-bottom: 14px;\n  }\n  @media(max-width:640px){ .summary-grid{ grid-template-columns: 1fr; } }\n\n  .sum-card {\n    background: var(--bg3);\n    border: 1px solid var(--border2);\n    padding: 14px;\n  }\n  .sc-label {\n    font-family: var(--sans);\n    font-size: 10px;\n    letter-spacing: 2px;\n    text-transform: uppercase;\n    font-weight: 600;\n    color: var(--text3);\n    margin-bottom: 6px;\n  }\n  .sc-val {\n    font-size: 12px;\n    color: var(--text);\n    line-height: 1.6;\n  }\n\n  .next-step {\n    background: linear-gradient(135deg, rgba(0,255,136,0.08), rgba(0,212,255,0.05));\n    border: 1px solid rgba(0,255,136,0.3);\n    padding: 14px 18px;\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    flex-wrap: wrap;\n    gap: 10px;\n  }\n  .ns-text {\n    font-family: var(--sans);\n    font-weight: 600;\n    font-size: 14px;\n    color: var(--green);\n  }\n  .ns-sub { font-size: 11px; color: var(--text3); margin-top: 2px; }\n  .ns-cmd {\n    background: var(--bg);\n    border: 1px solid var(--border);\n    padding: 6px 16px;\n    font-size: 12px;\n    color: var(--green);\n    cursor: pointer;\n    font-family: var(--mono);\n    transition: all 0.2s;\n  }\n  .ns-cmd:hover { background: rgba(0,255,136,0.1); border-color: var(--green); }\n\n  /* info line */\n  .info { \n    display: flex;\n    align-items: flex-start;\n    gap: 8px;\n    padding: 8px 12px;\n    background: rgba(0,212,255,0.06);\n    border-left: 3px solid var(--cyan);\n    margin: 10px 0;\n    font-size: 12px;\n    color: var(--text2);\n  }\n  .info-icon { color: var(--cyan); flex-shrink: 0; }\n\n  .warn {\n    display: flex;\n    align-items: flex-start;\n    gap: 8px;\n    padding: 8px 12px;\n    background: rgba(255,215,0,0.06);\n    border-left: 3px solid var(--yellow);\n    margin: 10px 0;\n    font-size: 12px;\n    color: var(--text2);\n  }\n\n  .highlight { color: var(--green); font-weight: 600; }\n  .hl-cyan { color: var(--cyan); }\n  .hl-yellow { color: var(--yellow); }\n  .hl-orange { color: var(--orange); }\n  .hl-red { color: var(--red); }\n  .hl-purple { color: var(--purple); }\n\n  .divider {\n    height: 1px;\n    background: linear-gradient(to right, transparent, var(--border), transparent);\n    margin: 14px 0;\n  }\n\n  /* stat bar */\n  .stat-row {\n    display: flex;\n    align-items: center;\n    gap: 10px;\n    margin: 5px 0;\n    font-size: 11.5px;\n  }\n  .stat-label { width: 120px; min-width: 120px; color: var(--text3); font-family: var(--sans); font-size: 11px; }\n  .stat-bar-bg { flex: 1; height: 6px; background: rgba(255,255,255,0.05); border-radius: 0; overflow: hidden; }\n  .stat-bar { height: 100%; border-radius: 0; }\n  .stat-val { width: 40px; text-align: right; color: var(--text2); font-size: 11px; }\n\n  .footnote {\n    font-size: 10px;\n    color: var(--text3);\n    margin-top: 8px;\n    letter-spacing: 0.5px;\n  }\n\n  /* scrollbar */\n  ::-webkit-scrollbar { width: 6px; }\n  ::-webkit-scrollbar-track { background: var(--bg); }\n  ::-webkit-scrollbar-thumb { background: var(--border); }";
const markup = "<div class=\"container\">\n\n  <!-- ═══ HEADER ═══ -->\n  <div class=\"sys-header\">\n    <div class=\"header-row\">\n      <div>\n        <div class=\"step-badge\">■ STEP 01 / MODULE 1 ● ACTIVE</div>\n        <div class=\"lesson-title\">What Exactly Is <span>Linux</span>?</div>\n        <div class=\"meta-tags\" style=\"margin-top:10px;\">\n          <span class=\"tag tag-green\">● Beginner</span>\n          <span class=\"tag tag-cyan\">⊞ Operating Systems</span>\n          <span class=\"tag tag-yellow\">⊛ System Architecture</span>\n          <span class=\"tag tag-purple\">⬡ Security</span>\n          <span class=\"tag tag-orange\">⊕ Enterprise</span>\n        </div>\n      </div>\n      <div class=\"sys-info\">\n        <div>HOST: <span>linux-lab-01</span></div>\n        <div>KERNEL: <span>6.x.x-generic</span></div>\n        <div>ARCH: <span>x86_64</span></div>\n        <div>UPTIME: <span>∞</span></div>\n        <div style=\"margin-top:6px;font-size:10px;color:#1e6a3a;\">▓▓▓▓▓▓▓░░░ LESSON LOADED</div>\n      </div>\n    </div>\n  </div>\n\n  <!-- ═══ 1. CONCEPT EXPLANATION ═══ -->\n  <div class=\"panel\">\n    <div class=\"panel-header\">\n      <span class=\"panel-icon\">◈</span>\n      <span class=\"panel-title\">Concept Explanation</span>\n      <span class=\"panel-num\">PANEL 01</span>\n    </div>\n    <div class=\"panel-body\">\n      <div class=\"concept-grid\">\n\n        <div class=\"concept-block\">\n          <div class=\"cb-title\">What is an Operating System?</div>\n          <div class=\"cb-text\">\n            An <span class=\"highlight\">Operating System (OS)</span> is the master software layer that sits between your hardware and your applications. It manages every resource — CPU cycles, memory pages, disk I/O, network packets — and provides a controlled, abstracted interface so programs don't talk to hardware directly.\n            <div class=\"divider\"></div>\n            Without an OS: every program would need to know exact hardware specs. With an OS: programs call standardized functions — the OS does the rest.\n          </div>\n        </div>\n\n        <div class=\"concept-block green\">\n          <div class=\"cb-title\">What is the Linux Kernel?</div>\n          <div class=\"cb-text\">\n            The <span class=\"highlight\">Linux kernel</span> is the core engine — written in C by Linus Torvalds in 1991. It is a <span class=\"highlight\">monolithic kernel</span>, meaning all core OS functions (process scheduling, memory management, device drivers, file systems) run in a single privileged address space (kernel space).\n            <div class=\"divider\"></div>\n            The kernel is <em>not</em> the full OS — it's the brain. Everything else is built on top.\n          </div>\n        </div>\n\n        <div class=\"concept-block yellow\">\n          <div class=\"cb-title\">GNU/Linux — The Full Picture</div>\n          <div class=\"cb-text\">\n            Linux = <span class=\"hl-yellow\">Kernel only</span>. <br>\n            GNU/Linux = Kernel + GNU userland tools (bash, coreutils, glibc, gcc…)<br><br>\n            When you use Ubuntu, Fedora, or Kali — you're using the Linux kernel + GNU tools + a distribution's package ecosystem, configs, and desktop/server software on top.\n          </div>\n        </div>\n\n        <div class=\"concept-block purple\">\n          <div class=\"cb-title\">What is a Linux Distribution?</div>\n          <div class=\"cb-text\">\n            A <span class=\"hl-purple\">distro</span> packages the Linux kernel with: a package manager, default software, configuration files, init system (systemd), and target-specific tools.<br><br>\n            Examples: Ubuntu (general), RHEL (enterprise servers), Kali (penetration testing), Alpine (containers), Arch (custom builds).\n          </div>\n        </div>\n\n        <div class=\"concept-block orange\">\n          <div class=\"cb-title\">Open Source &amp; Licensing</div>\n          <div class=\"cb-text\">\n            Linux is released under <span class=\"hl-orange\">GPLv2</span> (GNU General Public License). Anyone can: view, modify, and redistribute the source — as long as derivative works remain GPL-licensed.<br><br>\n            This enabled an entire ecosystem: Android (Linux kernel), AWS EC2, Docker, embedded IoT devices, supercomputers — all built on freely available source.\n          </div>\n        </div>\n\n        <div class=\"concept-block\">\n          <div class=\"cb-title\">Why Linux Matters</div>\n          <div class=\"cb-text\">\n            <span class=\"highlight\">96.3%</span> of top web servers run Linux.<br>\n            <span class=\"highlight\">100%</span> of the top 500 supercomputers run Linux.<br>\n            <span class=\"highlight\">~72%</span> of cloud infrastructure runs Linux.<br>\n            <span class=\"highlight\">~90%</span> of cybersecurity tools target/run on Linux.<br>\n            <div class=\"divider\"></div>\n            Linux is the default infrastructure layer of the modern internet.\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- ═══ 2. ARCHITECTURE DIAGRAM ═══ -->\n  <div class=\"panel\">\n    <div class=\"panel-header\">\n      <span class=\"panel-icon\">◫</span>\n      <span class=\"panel-title\">Linux System Architecture — Layer Model</span>\n      <span class=\"panel-num\">PANEL 02</span>\n    </div>\n    <div class=\"panel-body\">\n      <div class=\"arch-diagram\">\n        <div class=\"arch-layers\">\n\n          <div class=\"layer l-app\">\n            <div class=\"layer-label\" style=\"color:#5599ff;\">USER APPS</div>\n            <div class=\"layer-box\" style=\"border-color:rgba(41,121,255,0.5);background:rgba(41,121,255,0.07);\">\n              <div class=\"layer-name\" style=\"color:#5599ff;\">Application Layer</div>\n              <div class=\"layer-sub\">Programs running in user space — no direct hardware access</div>\n              <div class=\"layer-components\">\n                <span class=\"lc\">bash</span><span class=\"lc\">nginx</span><span class=\"lc\">python</span>\n                <span class=\"lc\">ssh client</span><span class=\"lc\">vim</span><span class=\"lc\">firefox</span>\n              </div>\n            </div>\n          </div>\n\n          <div class=\"layer-arrow\">↕ System Call Interface (ABI Boundary)</div>\n\n          <div class=\"layer l-shell\">\n            <div class=\"layer-label\" style=\"color:var(--cyan);\">SHELL/LIBS</div>\n            <div class=\"layer-box\" style=\"border-color:rgba(0,212,255,0.5);background:rgba(0,212,255,0.07);\">\n              <div class=\"layer-name\" style=\"color:var(--cyan);\">GNU C Library (glibc) + Shell</div>\n              <div class=\"layer-sub\">Wraps system calls into friendly functions. Shell interprets commands.</div>\n              <div class=\"layer-components\">\n                <span class=\"lc\">glibc</span><span class=\"lc\">bash</span><span class=\"lc\">zsh</span>\n                <span class=\"lc\">libpthread</span><span class=\"lc\">libssl</span>\n              </div>\n            </div>\n          </div>\n\n          <div class=\"layer-arrow\">↕ System Calls: open(), read(), write(), fork(), exec(), mmap()…</div>\n\n          <div class=\"layer l-kernel\">\n            <div class=\"layer-label\" style=\"color:var(--yellow);\">KERNEL</div>\n            <div class=\"layer-box\" style=\"border-color:rgba(255,215,0,0.6);background:rgba(255,215,0,0.08);\">\n              <div class=\"layer-name\" style=\"color:var(--yellow);\">Linux Kernel (Privileged / Ring 0)</div>\n              <div class=\"layer-sub\">The monolithic core — runs in kernel space with full hardware access</div>\n              <div class=\"layer-components\">\n                <span class=\"lc\" style=\"color:var(--yellow);\">Process Mgr</span>\n                <span class=\"lc\" style=\"color:var(--yellow);\">Memory Mgr</span>\n                <span class=\"lc\" style=\"color:var(--yellow);\">VFS</span>\n                <span class=\"lc\" style=\"color:var(--yellow);\">Net Stack</span>\n                <span class=\"lc\" style=\"color:var(--yellow);\">IPC</span>\n                <span class=\"lc\" style=\"color:var(--yellow);\">Security (LSM)</span>\n                <span class=\"lc\" style=\"color:var(--yellow);\">Device Drivers</span>\n                <span class=\"lc\" style=\"color:var(--yellow);\">Scheduler</span>\n              </div>\n            </div>\n          </div>\n\n          <div class=\"layer-arrow\">↕ Hardware Abstraction / IRQ / DMA</div>\n\n          <div class=\"layer l-hw\">\n            <div class=\"layer-label\" style=\"color:var(--orange);\">HARDWARE</div>\n            <div class=\"layer-box\" style=\"border-color:rgba(255,140,0,0.5);background:rgba(255,140,0,0.07);\">\n              <div class=\"layer-name\" style=\"color:var(--orange);\">Physical Hardware</div>\n              <div class=\"layer-sub\">CPU, RAM, Storage, NIC, GPU, USB, Sensors</div>\n              <div class=\"layer-components\">\n                <span class=\"lc\">CPU</span><span class=\"lc\">RAM</span><span class=\"lc\">NVMe/SSD</span>\n                <span class=\"lc\">NIC</span><span class=\"lc\">GPU</span><span class=\"lc\">BIOS/UEFI</span>\n              </div>\n            </div>\n          </div>\n        </div>\n\n        <!-- Kernel Internals Box -->\n        <div class=\"kernel-box\">\n          <div class=\"kernel-title\">🔶 Kernel Internal Subsystems</div>\n          <div class=\"kernel-grid\">\n            <div class=\"kc\">\n              <span class=\"kc-icon\">⚙</span>\n              <div class=\"kc-name\">Process Scheduler</div>\n              <div class=\"kc-desc\">CFS — Completely Fair Scheduler. Assigns CPU time.</div>\n            </div>\n            <div class=\"kc\">\n              <span class=\"kc-icon\">◫</span>\n              <div class=\"kc-name\">Memory Manager</div>\n              <div class=\"kc-desc\">Virtual memory, paging, swap, mmap.</div>\n            </div>\n            <div class=\"kc\">\n              <span class=\"kc-icon\">📂</span>\n              <div class=\"kc-name\">VFS Layer</div>\n              <div class=\"kc-desc\">Abstracts ext4, xfs, tmpfs, proc, sys.</div>\n            </div>\n            <div class=\"kc\">\n              <span class=\"kc-icon\">🌐</span>\n              <div class=\"kc-name\">Network Stack</div>\n              <div class=\"kc-desc\">TCP/IP, sockets, netfilter, iptables.</div>\n            </div>\n            <div class=\"kc\">\n              <span class=\"kc-icon\">🔒</span>\n              <div class=\"kc-name\">LSM (Security)</div>\n              <div class=\"kc-desc\">SELinux, AppArmor, capabilities.</div>\n            </div>\n            <div class=\"kc\">\n              <span class=\"kc-icon\">🔌</span>\n              <div class=\"kc-name\">Device Drivers</div>\n              <div class=\"kc-desc\">NIC, block, USB, char drivers.</div>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"info\" style=\"margin-top:14px;\">\n          <span class=\"info-icon\">ℹ</span>\n          <span><strong style=\"color:var(--cyan);\">Key principle:</strong> User-space programs CANNOT directly access hardware. They must ask the kernel via <strong>system calls</strong>. This isolation is the foundation of Linux security and stability.</span>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- ═══ 3. WORKFLOW ═══ -->\n  <div class=\"panel\">\n    <div class=\"panel-header\">\n      <span class=\"panel-icon\">⇢</span>\n      <span class=\"panel-title\">Workflow — How a Command Executes in Linux</span>\n      <span class=\"panel-num\">PANEL 03</span>\n    </div>\n    <div class=\"panel-body\">\n      <div class=\"workflow\">\n        <div class=\"wf-step\">\n          <div class=\"wf-line\"></div>\n          <div class=\"wf-dot\">1</div>\n          <div class=\"wf-content\">\n            <div class=\"wf-title\">User types command in terminal</div>\n            <div class=\"wf-desc\">You type <code>ls -la /etc</code> and press Enter. The terminal emulator captures your keystrokes.</div>\n            <div class=\"wf-cmd\">$ ls -la /etc</div>\n          </div>\n        </div>\n        <div class=\"wf-step\">\n          <div class=\"wf-line\"></div>\n          <div class=\"wf-dot\">2</div>\n          <div class=\"wf-content\">\n            <div class=\"wf-title\">Shell parses the command</div>\n            <div class=\"wf-desc\">Bash/Zsh tokenizes the input: command=<span class=\"highlight\">ls</span>, flags=<span class=\"highlight\">-la</span>, argument=<span class=\"highlight\">/etc</span>. Shell looks up <code>ls</code> in PATH → finds <code>/bin/ls</code>.</div>\n          </div>\n        </div>\n        <div class=\"wf-step\">\n          <div class=\"wf-line\"></div>\n          <div class=\"wf-dot\">3</div>\n          <div class=\"wf-content\">\n            <div class=\"wf-title\">Shell calls fork() + exec()</div>\n            <div class=\"wf-desc\">Shell issues <code>fork()</code> system call → kernel creates a child process. Then <code>execve(\"/bin/ls\", [\"ls\",\"-la\",\"/etc\"], envp)</code> → kernel loads the <code>ls</code> binary into the child process memory.</div>\n          </div>\n        </div>\n        <div class=\"wf-step\">\n          <div class=\"wf-line\"></div>\n          <div class=\"wf-dot\">4</div>\n          <div class=\"wf-content\">\n            <div class=\"wf-title\">Kernel executes ls — permission &amp; syscall chain</div>\n            <div class=\"wf-desc\"><code>ls</code> calls <code>openat()</code> → kernel checks DAC permissions on <code>/etc</code>. Then <code>getdents64()</code> → kernel reads directory entries from ext4. Returns data to user-space buffer.</div>\n          </div>\n        </div>\n        <div class=\"wf-step\">\n          <div class=\"wf-line\"></div>\n          <div class=\"wf-dot\">5</div>\n          <div class=\"wf-content\">\n            <div class=\"wf-title\">Output written to stdout</div>\n            <div class=\"wf-desc\"><code>ls</code> formats the directory listing and calls <code>write(1, buffer, len)</code> → kernel writes to file descriptor 1 (stdout) → terminal displays the output on screen.</div>\n          </div>\n        </div>\n        <div class=\"wf-step\">\n          <div class=\"wf-dot\">6</div>\n          <div class=\"wf-content\">\n            <div class=\"wf-title\">Process exits, shell resumes</div>\n            <div class=\"wf-desc\"><code>ls</code> calls <code>exit(0)</code>. Kernel cleans up process resources. Shell's <code>wait()</code> returns, shell prints new prompt. Round trip: typically &lt;5ms.</div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- ═══ 4. TERMINAL SIMULATION ═══ -->\n  <div class=\"panel\">\n    <div class=\"panel-header\">\n      <span class=\"panel-icon\">▶</span>\n      <span class=\"panel-title\">Terminal Simulation — Exploring the System</span>\n      <span class=\"panel-num\">PANEL 04</span>\n    </div>\n    <div class=\"panel-body\">\n      <div class=\"terminal\">\n        <div class=\"term-bar\">\n          <div class=\"term-dot td-red\"></div>\n          <div class=\"term-dot td-yellow\"></div>\n          <div class=\"term-dot td-green\"></div>\n          <span class=\"term-title\">root@linux-lab:~ — bash — 120×40</span>\n        </div>\n        <div class=\"term-body\">\n          <span class=\"t-section\">──── IDENTIFY THE KERNEL ────</span>\n          <span class=\"t-line\"><span class=\"t-prompt\">root@lab:~# </span><span class=\"t-cmd\">uname -r</span></span>\n          <span class=\"t-out\">6.8.0-49-generic</span>\n          <span class=\"t-line\" style=\"margin-top:4px;\"><span class=\"t-prompt\">root@lab:~# </span><span class=\"t-cmd\">uname -a</span></span>\n          <span class=\"t-out\">Linux lab 6.8.0-49-generic #49-Ubuntu SMP x86_64 GNU/Linux</span>\n\n          <span class=\"t-section\">──── DISTRO IDENTIFICATION ────</span>\n          <span class=\"t-line\"><span class=\"t-prompt\">root@lab:~# </span><span class=\"t-cmd\">cat /etc/os-release</span></span>\n          <span class=\"t-out2\">NAME=\"Ubuntu\"</span>\n          <span class=\"t-out2\">VERSION=\"24.04.1 LTS (Noble Numbat)\"</span>\n          <span class=\"t-out2\">ID=ubuntu</span>\n          <span class=\"t-out2\">ID_LIKE=debian</span>\n\n          <span class=\"t-section\">──── CPU ARCHITECTURE ────</span>\n          <span class=\"t-line\"><span class=\"t-prompt\">root@lab:~# </span><span class=\"t-cmd\">lscpu | grep -E \"Architecture|CPU\\(s\\)|Model name\"</span></span>\n          <span class=\"t-out\">Architecture:   x86_64</span>\n          <span class=\"t-out\">CPU(s):         4</span>\n          <span class=\"t-out\">Model name:     Intel(R) Core(TM) i7-12700K</span>\n\n          <span class=\"t-section\">──── KERNEL MODULES (LOADED DRIVERS) ────</span>\n          <span class=\"t-line\"><span class=\"t-prompt\">root@lab:~# </span><span class=\"t-cmd\">lsmod | head -8</span></span>\n          <span class=\"t-out\">Module                  Size  Used by</span>\n          <span class=\"t-out\">nf_conntrack          172032  2 nf_nat,iptable_nat</span>\n          <span class=\"t-out\">ext4                  970752  1</span>\n          <span class=\"t-out\">nvidia               3456000  45</span>\n\n          <span class=\"t-section\">──── SYSTEM CALLS MADE BY ls (strace) ────</span>\n          <span class=\"t-line\"><span class=\"t-prompt\">root@lab:~# </span><span class=\"t-cmd\">strace -c ls /etc 2>&1 | tail -8</span></span>\n          <span class=\"t-out\">% time   seconds  calls  syscall</span>\n          <span class=\"t-out\">──────────────────────────────────</span>\n          <span class=\"t-out3\"> 45.2    0.000124    342  getdents64</span>\n          <span class=\"t-out3\"> 22.1    0.000061     12  openat</span>\n          <span class=\"t-out3\"> 18.3    0.000050      8  fstat</span>\n          <span class=\"t-out3\">  9.4    0.000026      4  mmap</span>\n\n          <span class=\"t-section\">──── WHERE IS LINUX IN USE RIGHT NOW? ────</span>\n          <span class=\"t-line\"><span class=\"t-prompt\">root@lab:~# </span><span class=\"t-cmd\">cat /proc/version</span></span>\n          <span class=\"t-out\">Linux version 6.8.0-49-generic (buildd@lcy02-amd64-005)</span>\n          <span class=\"t-out\">(gcc version 13.2.0 (Ubuntu 13.2.0-23ubuntu4)) #49-Ubuntu</span>\n\n          <span class=\"t-section\">──── PROCESS TREE ────</span>\n          <span class=\"t-line\"><span class=\"t-prompt\">root@lab:~# </span><span class=\"t-cmd\">pstree -p | head -12</span></span>\n          <span class=\"t-out\">systemd(1)─┬─cron(892)</span>\n          <span class=\"t-out\">           ├─sshd(1102)───sshd(2341)───bash(2342)───pstree(3891)</span>\n          <span class=\"t-out\">           ├─nginx(1500)─┬─nginx(1501)</span>\n          <span class=\"t-out\">           │             └─nginx(1502)</span>\n          <span class=\"t-out\">           └─dockerd(1890)───containerd(1922)</span>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- ═══ 5. WHERE IS LINUX USED ═══ -->\n  <div class=\"panel\">\n    <div class=\"panel-header\">\n      <span class=\"panel-icon\">◎</span>\n      <span class=\"panel-title\">Where Linux Is Deployed — Real-World Domains</span>\n      <span class=\"panel-num\">PANEL 05</span>\n    </div>\n    <div class=\"panel-body\">\n      <div class=\"use-grid\">\n        <div class=\"use-card\">\n          <div class=\"uc-icon\">🌐</div>\n          <div class=\"uc-name\">Web Servers</div>\n          <div class=\"uc-desc\">Apache, Nginx, Caddy run on Linux. Powers 96%+ of public web servers.</div>\n          <div class=\"uc-pct\" style=\"color:var(--green);\">96.3% market share</div>\n        </div>\n        <div class=\"use-card\">\n          <div class=\"uc-icon\">☁️</div>\n          <div class=\"uc-name\">Cloud Infrastructure</div>\n          <div class=\"uc-desc\">AWS EC2, GCP Compute, Azure VMs default to Linux. Kubernetes nodes run Linux.</div>\n          <div class=\"uc-pct\" style=\"color:var(--cyan);\">~72% cloud VMs</div>\n        </div>\n        <div class=\"use-card\">\n          <div class=\"uc-icon\">🔒</div>\n          <div class=\"uc-name\">Cybersecurity</div>\n          <div class=\"uc-desc\">Kali Linux for pentesting. Security tools: nmap, Wireshark, Metasploit all run on Linux.</div>\n          <div class=\"uc-pct\" style=\"color:var(--red);\">~90% security tools</div>\n        </div>\n        <div class=\"use-card\">\n          <div class=\"uc-icon\">🐳</div>\n          <div class=\"uc-name\">Containers</div>\n          <div class=\"uc-desc\">Docker containers use Linux namespaces + cgroups. All container hosts run Linux kernel.</div>\n          <div class=\"uc-pct\" style=\"color:var(--blue);\">100% of containers</div>\n        </div>\n        <div class=\"use-card\">\n          <div class=\"uc-icon\">⚡</div>\n          <div class=\"uc-name\">Supercomputers</div>\n          <div class=\"uc-desc\">All top 500 supercomputers in the world run Linux.</div>\n          <div class=\"uc-pct\" style=\"color:var(--yellow);\">500/500 top HPC</div>\n        </div>\n        <div class=\"use-card\">\n          <div class=\"uc-icon\">📱</div>\n          <div class=\"uc-name\">Embedded / IoT</div>\n          <div class=\"uc-desc\">Routers, smart TVs, Android phones (Linux kernel), industrial PLCs.</div>\n          <div class=\"uc-pct\" style=\"color:var(--orange);\">Billions of devices</div>\n        </div>\n      </div>\n\n      <div style=\"margin-top:16px;\">\n        <div class=\"cb-text\" style=\"margin-bottom:10px;font-family:var(--sans);font-size:12px;color:var(--text3);letter-spacing:1px;text-transform:uppercase;\">Linux vs Windows market share by domain</div>\n        <div class=\"stat-row\">\n          <span class=\"stat-label\">Web Servers</span>\n          <div class=\"stat-bar-bg\"><div class=\"stat-bar\" style=\"width:96%;background:var(--green);\"></div></div>\n          <span class=\"stat-val\" style=\"color:var(--green);\">96%</span>\n        </div>\n        <div class=\"stat-row\">\n          <span class=\"stat-label\">Cloud VMs</span>\n          <div class=\"stat-bar-bg\"><div class=\"stat-bar\" style=\"width:72%;background:var(--cyan);\"></div></div>\n          <span class=\"stat-val\" style=\"color:var(--cyan);\">72%</span>\n        </div>\n        <div class=\"stat-row\">\n          <span class=\"stat-label\">Supercomputers</span>\n          <div class=\"stat-bar-bg\"><div class=\"stat-bar\" style=\"width:100%;background:var(--yellow);\"></div></div>\n          <span class=\"stat-val\" style=\"color:var(--yellow);\">100%</span>\n        </div>\n        <div class=\"stat-row\">\n          <span class=\"stat-label\">Desktop PCs</span>\n          <div class=\"stat-bar-bg\"><div class=\"stat-bar\" style=\"width:4%;background:var(--purple);\"></div></div>\n          <span class=\"stat-val\" style=\"color:var(--purple);\">4%</span>\n        </div>\n        <div class=\"footnote\">Source: w3techs, Top500.org, StatCounter — Linux share by deployment category</div>\n      </div>\n    </div>\n  </div>\n\n  <!-- ═══ 6. DISTRO TREE ═══ -->\n  <div class=\"panel\">\n    <div class=\"panel-header\">\n      <span class=\"panel-icon\">⊞</span>\n      <span class=\"panel-title\">Linux Distribution Ecosystem</span>\n      <span class=\"panel-num\">PANEL 06</span>\n    </div>\n    <div class=\"panel-body\">\n      <div class=\"distro-tree\">\n        <div class=\"dt-root\">🐧 Linux Kernel (Linus Torvalds, 1991)</div>\n        <div class=\"dt-indent1\">│</div>\n        <div class=\"dt-indent1\">├── <span class=\"dt-branch\">Debian Family</span></div>\n        <div class=\"dt-indent2\">├── <span class=\"dt-leaf\">Ubuntu</span> — general purpose, desktop &amp; server</div>\n        <div class=\"dt-indent2\">├── <span class=\"dt-leaf\">Kali Linux</span> — penetration testing / offensive security</div>\n        <div class=\"dt-indent2\">├── <span class=\"dt-leaf\">Parrot OS</span> — security &amp; forensics</div>\n        <div class=\"dt-indent2\">└── <span class=\"dt-leaf\">Raspberry Pi OS</span> — embedded / IoT</div>\n        <div class=\"dt-indent1\">│</div>\n        <div class=\"dt-indent1\">├── <span class=\"dt-branch\">Red Hat Family</span></div>\n        <div class=\"dt-indent2\">├── <span class=\"dt-leaf\">RHEL</span> — enterprise production servers (paid)</div>\n        <div class=\"dt-indent2\">├── <span class=\"dt-leaf\">CentOS / AlmaLinux / Rocky</span> — RHEL-compatible free</div>\n        <div class=\"dt-indent2\">└── <span class=\"dt-leaf\">Fedora</span> — cutting-edge, upstream for RHEL</div>\n        <div class=\"dt-indent1\">│</div>\n        <div class=\"dt-indent1\">├── <span class=\"dt-branch\">SUSE Family</span></div>\n        <div class=\"dt-indent2\">├── <span class=\"dt-leaf\">SLES</span> — SUSE Linux Enterprise Server</div>\n        <div class=\"dt-indent2\">└── <span class=\"dt-leaf\">openSUSE</span> — community version</div>\n        <div class=\"dt-indent1\">│</div>\n        <div class=\"dt-indent1\">├── <span class=\"dt-branch\">Arch Family</span></div>\n        <div class=\"dt-indent2\">├── <span class=\"dt-leaf\">Arch Linux</span> — rolling release, manual config</div>\n        <div class=\"dt-indent2\">└── <span class=\"dt-leaf\">Manjaro</span> — user-friendly Arch</div>\n        <div class=\"dt-indent1\">│</div>\n        <div class=\"dt-indent1\">└── <span class=\"dt-branch\">Minimal / Specialized</span></div>\n        <div class=\"dt-indent2\">├── <span class=\"dt-leaf\">Alpine Linux</span> — ultra-small, container base images</div>\n        <div class=\"dt-indent2\">├── <span class=\"dt-leaf\">Android</span> — Linux kernel, mobile</div>\n        <div class=\"dt-indent2\">└── <span class=\"dt-leaf\">CoreOS / Flatcar</span> — container-optimized clusters</div>\n      </div>\n    </div>\n  </div>\n\n  <!-- ═══ 7. LINUX VS WINDOWS ═══ -->\n  <div class=\"panel\">\n    <div class=\"panel-header\">\n      <span class=\"panel-icon\">⇄</span>\n      <span class=\"panel-title\">Linux vs Windows — Deep Technical Comparison</span>\n      <span class=\"panel-num\">PANEL 07</span>\n    </div>\n    <div class=\"panel-body\">\n      <table class=\"compare-table\">\n        <thead>\n          <tr>\n            <th>Dimension</th>\n            <th>🐧 Linux</th>\n            <th>🪟 Windows</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Kernel Type</td>\n            <td><span class=\"yes\">Monolithic</span> — all subsystems in kernel space, fast IPC</td>\n            <td><span class=\"hl-cyan\">Hybrid</span> — NT kernel; some services in user-mode (CSRSS, LSASS)</td>\n          </tr>\n          <tr>\n            <td>Kernel written in</td>\n            <td>C + ASM (GCC)</td>\n            <td>C, C++ (MSVC)</td>\n          </tr>\n          <tr>\n            <td>Source code</td>\n            <td><span class=\"yes\">Open source (GPLv2)</span> — fully auditable</td>\n            <td><span class=\"no\">Closed source</span> — proprietary (limited WDK access)</td>\n          </tr>\n          <tr>\n            <td>File System</td>\n            <td>ext4, xfs, btrfs, zfs, tmpfs, proc, sysfs</td>\n            <td>NTFS, ReFS, FAT32, exFAT</td>\n          </tr>\n          <tr>\n            <td>Path Separator</td>\n            <td><span class=\"yes\">/ (forward slash)</span></td>\n            <td>\\ (backslash) — legacy DOS heritage</td>\n          </tr>\n          <tr>\n            <td>Permissions Model</td>\n            <td>DAC (rwx) + ACLs + Capabilities + LSM (SELinux/AppArmor)</td>\n            <td>NTFS ACLs + UAC (User Account Control)</td>\n          </tr>\n          <tr>\n            <td>Root / Admin</td>\n            <td>root (UID 0) — explicit privilege escalation via sudo</td>\n            <td>SYSTEM / Administrator — UAC elevation prompt</td>\n          </tr>\n          <tr>\n            <td>Process Scheduler</td>\n            <td>CFS (Completely Fair Scheduler) + real-time classes</td>\n            <td>Priority-based preemptive + UMS (user-mode scheduling)</td>\n          </tr>\n          <tr>\n            <td>Package Management</td>\n            <td>apt/dnf/pacman — centralized signed repositories</td>\n            <td>winget, MSI, .exe installers — no universal repo</td>\n          </tr>\n          <tr>\n            <td>Configuration</td>\n            <td>Plain text files in /etc — human readable, version control friendly</td>\n            <td>Registry (binary hive) + XML files + GUI</td>\n          </tr>\n          <tr>\n            <td>Services / Init</td>\n            <td>systemd (units, targets, journald)</td>\n            <td>Windows Services (SCM), Task Scheduler</td>\n          </tr>\n          <tr>\n            <td>Logging</td>\n            <td>journalctl, syslog, /var/log/* — plain text + structured</td>\n            <td>Event Viewer (.evtx binary format)</td>\n          </tr>\n          <tr>\n            <td>Networking Config</td>\n            <td>ip, nmcli, /etc/network/interfaces, netplan</td>\n            <td>NCPA, netsh, PowerShell, Registry</td>\n          </tr>\n          <tr>\n            <td>Firewall</td>\n            <td>iptables / nftables / ufw — kernel netfilter</td>\n            <td>Windows Defender Firewall (wf.msc)</td>\n          </tr>\n          <tr>\n            <td>Remote Access</td>\n            <td>SSH (default, certificate-based) — encrypted by design</td>\n            <td>RDP (GUI-based) — historically had many CVEs</td>\n          </tr>\n          <tr>\n            <td>Automation</td>\n            <td>Bash, Python, Ansible, cron — native scripting everything</td>\n            <td>PowerShell, Task Scheduler, GPO</td>\n          </tr>\n          <tr>\n            <td>Attack Surface</td>\n            <td>Smaller default install, no GUI required, granular controls</td>\n            <td>Larger by default — many services auto-enabled</td>\n          </tr>\n          <tr>\n            <td>Malware prevalence</td>\n            <td>Lower (permission model, open source)</td>\n            <td>Higher historical target (90%+ malware targets Windows)</td>\n          </tr>\n          <tr>\n            <td>Memory usage (idle)</td>\n            <td>~80–200 MB (headless server)</td>\n            <td>~1.5–2.5 GB (minimal install)</td>\n          </tr>\n          <tr>\n            <td>License Cost</td>\n            <td><span class=\"yes\">Free (most distros)</span></td>\n            <td><span class=\"no\">$99–$499+ per license</span></td>\n          </tr>\n        </tbody>\n      </table>\n    </div>\n  </div>\n\n  <!-- ═══ 8. SECURITY PANEL ═══ -->\n  <div class=\"panel\">\n    <div class=\"panel-header\">\n      <span class=\"panel-icon\">⚠</span>\n      <span class=\"panel-title\">Security Perspective — Linux Threat Model &amp; Defenses</span>\n      <span class=\"panel-num\">PANEL 08</span>\n    </div>\n    <div class=\"panel-body\">\n      <div class=\"sec-grid\">\n        <div class=\"sec-block\">\n          <div class=\"sb-title red\">⛔ Attack Vectors (Red Team)</div>\n          <ul class=\"sb-list\">\n            <li>Kernel exploits — privilege escalation via kernel bugs (e.g., Dirty COW CVE-2016-5195)</li>\n            <li>SUID binary abuse — misconfigured setuid programs run as root</li>\n            <li>Weak SSH — password auth, no key hardening, default port 22</li>\n            <li>Misconfigured sudo — NOPASSWD rules or wildcard commands</li>\n            <li>World-writable scripts in cron — attacker modifies, root executes</li>\n            <li>PATH hijacking — malicious binary before system binary in PATH</li>\n            <li>Exposed services — Redis, Memcached, Elasticsearch open to internet</li>\n          </ul>\n        </div>\n        <div class=\"sec-block\">\n          <div class=\"sb-title green\">✔ Defensive Controls (Blue Team)</div>\n          <ul class=\"sb-list\">\n            <li>SELinux / AppArmor — mandatory access control, confines processes</li>\n            <li>Principle of least privilege — limit sudo, use capabilities not full root</li>\n            <li>SSH hardening — key-only auth, port knocking, fail2ban</li>\n            <li>Audit framework — auditd captures all system calls, file access</li>\n            <li>File integrity monitoring — AIDE, Tripwire detect unauthorized changes</li>\n            <li>Unattended upgrades — automated kernel/package patching</li>\n            <li>Firewall — nftables default-deny, allow only required ports</li>\n          </ul>\n        </div>\n      </div>\n      <div class=\"warn\" style=\"margin-top:12px;\">\n        <span style=\"color:var(--yellow);\">⚠</span>\n        <span><strong style=\"color:var(--yellow);\">Auditor note:</strong> On Linux, misconfigurations are more dangerous than malware. Check permissions, sudo rules, SUID binaries, and open ports before checking for viruses. Run <code>find / -perm -4000 2>/dev/null</code> to enumerate SUID binaries immediately on any new system assessment.</span>\n      </div>\n    </div>\n  </div>\n\n  <!-- ═══ 9. AUDITOR CHECKLIST ═══ -->\n  <div class=\"panel\">\n    <div class=\"panel-header\">\n      <span class=\"panel-icon\">✔</span>\n      <span class=\"panel-title\">Auditor / Security Checklist — Step 1 Verification</span>\n      <span class=\"panel-num\">PANEL 09</span>\n    </div>\n    <div class=\"panel-body\">\n      <ul class=\"checklist\">\n        <li>\n          <div class=\"chk\">✓</div>\n          Can you identify the kernel version and distro of any Linux system?\n          <span class=\"chk-domain tag tag-green\">KNOW-HOW</span>\n        </li>\n        <li>\n          <div class=\"chk\">✓</div>\n          Do you understand the user-space / kernel-space boundary and why it exists?\n          <span class=\"chk-domain tag tag-cyan\">ARCH</span>\n        </li>\n        <li>\n          <div class=\"chk\">✓</div>\n          Can you explain what a system call is and give 5 examples (open, read, write, fork, exec)?\n          <span class=\"chk-domain tag tag-yellow\">SYSCALL</span>\n        </li>\n        <li>\n          <div class=\"chk\">✓</div>\n          Do you understand the difference between a kernel and a distribution?\n          <span class=\"chk-domain tag tag-green\">CONCEPT</span>\n        </li>\n        <li>\n          <div class=\"chk\">✓</div>\n          Can you identify which Linux family (Debian/RHEL/Arch) a target system uses from package manager and file paths?\n          <span class=\"chk-domain tag tag-orange\">AUDIT</span>\n        </li>\n        <li>\n          <div class=\"chk\">✓</div>\n          Do you understand why Linux is the dominant OS in servers, cloud, and containers?\n          <span class=\"chk-domain tag tag-purple\">CONTEXT</span>\n        </li>\n        <li>\n          <div class=\"chk\">✓</div>\n          Can you explain the monolithic vs hybrid kernel difference between Linux and Windows NT?\n          <span class=\"chk-domain tag tag-cyan\">COMPARE</span>\n        </li>\n        <li>\n          <div class=\"chk\">✓</div>\n          Run <code>uname -a</code>, <code>lscpu</code>, <code>lsmod</code>, <code>cat /etc/os-release</code> on a real Linux system and interpret the output.\n          <span class=\"chk-domain tag tag-green\">LAB</span>\n        </li>\n      </ul>\n    </div>\n  </div>\n\n  <!-- ═══ 10. SUMMARY ═══ -->\n  <div class=\"panel\">\n    <div class=\"panel-header\">\n      <span class=\"panel-icon\">◉</span>\n      <span class=\"panel-title\">Summary — Step 1 Complete</span>\n      <span class=\"panel-num\">PANEL 10</span>\n    </div>\n    <div class=\"panel-body\">\n      <div class=\"summary-grid\">\n        <div class=\"sum-card\">\n          <div class=\"sc-label\">What You Learned</div>\n          <div class=\"sc-val\">Linux = kernel + GNU tools + distro layer. The kernel is monolithic, runs in Ring 0, manages all hardware via system calls. User space is isolated.</div>\n        </div>\n        <div class=\"sum-card\">\n          <div class=\"sc-label\">Why It Matters</div>\n          <div class=\"sc-val\">Every cloud VM, Docker container, K8s node, web server, and security tool runs on this architecture. Understanding it is foundational for admin, security, and auditing.</div>\n        </div>\n        <div class=\"sum-card\">\n          <div class=\"sc-label\">Where It's Used</div>\n          <div class=\"sc-val\">96% of web servers, 100% of supercomputers, all containers, most cloud infra, embedded IoT, Android phones, and all serious security tooling.</div>\n        </div>\n      </div>\n\n      <div class=\"next-step\">\n        <div>\n          <div class=\"ns-text\">▶ Next: Step 2 — Linux Architecture Deep Dive</div>\n          <div class=\"ns-sub\">Kernel internals · Process management · Memory management · VFS · IPC · Scheduling · Boot sequence · systemd</div>\n        </div>\n        <div class=\"ns-cmd\" onclick=\"window.sendPrompt && window.sendPrompt('Start Step 2')\">$ Start Step 2 →</div>\n      </div>\n    </div>\n  </div>\n\n</div>";

export default function LinuxStep1() {
  return <LessonDocument title="What Is Linux" styles={styles} markup={markup} />;
}
